// Deduplicate
const seen = new Set();
export const ANIME_POOL = ANIME_ID_POOL.filter(id => {
  if (seen.has(id)) return false;
  seen.add(id);
  return true;
});

export function pickRandomAnimeId() {
  return ANIME_POOL[Math.floor(Math.random() * ANIME_POOL.length)];
}